-- Additive DCIM taxonomy and cable metadata. Existing rows retain safe OTHER defaults.
ALTER TABLE infranexum_dcim.equipment_model
  ADD COLUMN IF NOT EXISTS equipment_category VARCHAR(40) NOT NULL DEFAULT 'OTHER',
  ADD COLUMN IF NOT EXISTS equipment_type VARCHAR(64) NOT NULL DEFAULT 'OTHER_EQUIPMENT',
  ADD COLUMN IF NOT EXISTS manufacturer_reference VARCHAR(160);

ALTER TABLE infranexum_dcim.equipment_model DROP CONSTRAINT IF EXISTS ck_inx_dcim_model_dims;
ALTER TABLE infranexum_dcim.equipment_model DROP CONSTRAINT IF EXISTS ck_inx_dcim_model_category;
ALTER TABLE infranexum_dcim.equipment_model DROP CONSTRAINT IF EXISTS ck_inx_dcim_model_type;
ALTER TABLE infranexum_dcim.equipment_model DROP CONSTRAINT IF EXISTS ck_inx_dcim_model_taxonomy;
ALTER TABLE infranexum_dcim.equipment_model DROP CONSTRAINT IF EXISTS ck_inx_dcim_model_rack_dims;
ALTER TABLE infranexum_dcim.equipment_model
  ADD CONSTRAINT ck_inx_dcim_model_dims CHECK (rack_units BETWEEN 0 AND 100 AND width_mm BETWEEN 0 AND 5000 AND depth_mm BETWEEN 0 AND 5000 AND weight_kg >= 0),
  ADD CONSTRAINT ck_inx_dcim_model_category CHECK (equipment_category IN ('SERVER','NETWORK','STORAGE','COMPUTER','PRINTING','POWER','DISK','MEMORY','RACK_INFRASTRUCTURE','SECURITY','TELECOM','AUDIO_VIDEO','ENVIRONMENT','PERIPHERAL','OTHER')),
  ADD CONSTRAINT ck_inx_dcim_model_type CHECK (equipment_type IN ('PHYSICAL_SERVER','BLADE_SERVER','BLADE_CHASSIS','HYPERCONVERGED_NODE','GPU_SERVER','EDGE_SERVER','MAINFRAME','VIRTUAL_MACHINE','ROUTER','CORE_SWITCH','DISTRIBUTION_SWITCH','ACCESS_SWITCH','FIREWALL','LOAD_BALANCER','WIRELESS_CONTROLLER','ACCESS_POINT','MODEM','SDWAN_APPLIANCE','NETWORK_APPLIANCE','PATCH_PANEL','TRANSCEIVER','STORAGE_ARRAY','SAN_ARRAY','NAS_APPLIANCE','OBJECT_STORAGE_NODE','HYPERCONVERGED_STORAGE','TAPE_LIBRARY','BACKUP_APPLIANCE','JBOD','DISK_SHELF','DESKTOP','WORKSTATION','LAPTOP','THIN_CLIENT','MINI_PC','KIOSK','LASER_PRINTER','INKJET_PRINTER','MULTIFUNCTION_PRINTER','LABEL_PRINTER','PLOTTER','DOCUMENT_SCANNER','UPS','RACK_PDU','FLOOR_PDU','ATS','STS','RECTIFIER','INVERTER','POWER_SUPPLY','POWER_STRIP','HDD','SSD_SATA','SSD_SAS','SSD_NVME','TAPE_DRIVE','RAM_DIMM','RAM_RDIMM','RAM_LRDIMM','RAM_SODIMM','NVRAM','RACK_CABINET','OPEN_FRAME_RACK','WALL_CABINET','KVM_CONSOLE','RACK_CONSOLE','CABLE_MANAGER','CCTV_CAMERA','VIDEO_RECORDER','ACCESS_CONTROL_PANEL','BADGE_READER','BIOMETRIC_READER','IP_PHONE','PBX','SESSION_BORDER_CONTROLLER','VOIP_GATEWAY','DECT_BASE','DISPLAY','PROJECTOR','CONFERENCE_SYSTEM','VIDEOCONFERENCE_CODEC','DIGITAL_SIGNAGE_PLAYER','ENVIRONMENT_SENSOR','TEMPERATURE_SENSOR','HUMIDITY_SENSOR','LEAK_SENSOR','AIRFLOW_SENSOR','CRAC','CRAH','HVAC_CONTROLLER','MONITOR','KEYBOARD','MOUSE','DOCKING_STATION','USB_HUB','EXTERNAL_DRIVE','OTHER_EQUIPMENT')),
  ADD CONSTRAINT ck_inx_dcim_model_taxonomy CHECK ((equipment_category='SERVER' AND equipment_type IN ('PHYSICAL_SERVER','BLADE_SERVER','BLADE_CHASSIS','HYPERCONVERGED_NODE','GPU_SERVER','EDGE_SERVER','MAINFRAME','VIRTUAL_MACHINE')) OR (equipment_category='NETWORK' AND equipment_type IN ('ROUTER','CORE_SWITCH','DISTRIBUTION_SWITCH','ACCESS_SWITCH','FIREWALL','LOAD_BALANCER','WIRELESS_CONTROLLER','ACCESS_POINT','MODEM','SDWAN_APPLIANCE','NETWORK_APPLIANCE','PATCH_PANEL','TRANSCEIVER')) OR (equipment_category='STORAGE' AND equipment_type IN ('STORAGE_ARRAY','SAN_ARRAY','NAS_APPLIANCE','OBJECT_STORAGE_NODE','HYPERCONVERGED_STORAGE','TAPE_LIBRARY','BACKUP_APPLIANCE','JBOD','DISK_SHELF')) OR (equipment_category='COMPUTER' AND equipment_type IN ('DESKTOP','WORKSTATION','LAPTOP','THIN_CLIENT','MINI_PC','KIOSK')) OR (equipment_category='PRINTING' AND equipment_type IN ('LASER_PRINTER','INKJET_PRINTER','MULTIFUNCTION_PRINTER','LABEL_PRINTER','PLOTTER','DOCUMENT_SCANNER')) OR (equipment_category='POWER' AND equipment_type IN ('UPS','RACK_PDU','FLOOR_PDU','ATS','STS','RECTIFIER','INVERTER','POWER_SUPPLY','POWER_STRIP')) OR (equipment_category='DISK' AND equipment_type IN ('HDD','SSD_SATA','SSD_SAS','SSD_NVME','TAPE_DRIVE')) OR (equipment_category='MEMORY' AND equipment_type IN ('RAM_DIMM','RAM_RDIMM','RAM_LRDIMM','RAM_SODIMM','NVRAM')) OR (equipment_category='RACK_INFRASTRUCTURE' AND equipment_type IN ('RACK_CABINET','OPEN_FRAME_RACK','WALL_CABINET','KVM_CONSOLE','RACK_CONSOLE','CABLE_MANAGER')) OR (equipment_category='SECURITY' AND equipment_type IN ('CCTV_CAMERA','VIDEO_RECORDER','ACCESS_CONTROL_PANEL','BADGE_READER','BIOMETRIC_READER')) OR (equipment_category='TELECOM' AND equipment_type IN ('IP_PHONE','PBX','SESSION_BORDER_CONTROLLER','VOIP_GATEWAY','DECT_BASE')) OR (equipment_category='AUDIO_VIDEO' AND equipment_type IN ('DISPLAY','PROJECTOR','CONFERENCE_SYSTEM','VIDEOCONFERENCE_CODEC','DIGITAL_SIGNAGE_PLAYER')) OR (equipment_category='ENVIRONMENT' AND equipment_type IN ('ENVIRONMENT_SENSOR','TEMPERATURE_SENSOR','HUMIDITY_SENSOR','LEAK_SENSOR','AIRFLOW_SENSOR','CRAC','CRAH','HVAC_CONTROLLER')) OR (equipment_category='PERIPHERAL' AND equipment_type IN ('MONITOR','KEYBOARD','MOUSE','DOCKING_STATION','USB_HUB','EXTERNAL_DRIVE')) OR (equipment_category='OTHER' AND equipment_type IN ('OTHER_EQUIPMENT'))),
  ADD CONSTRAINT ck_inx_dcim_model_rack_dims CHECK (equipment_type NOT IN ('PHYSICAL_SERVER','BLADE_SERVER','BLADE_CHASSIS','HYPERCONVERGED_NODE','GPU_SERVER','EDGE_SERVER','ROUTER','CORE_SWITCH','DISTRIBUTION_SWITCH','ACCESS_SWITCH','FIREWALL','LOAD_BALANCER','WIRELESS_CONTROLLER','SDWAN_APPLIANCE','NETWORK_APPLIANCE','PATCH_PANEL','STORAGE_ARRAY','SAN_ARRAY','NAS_APPLIANCE','OBJECT_STORAGE_NODE','HYPERCONVERGED_STORAGE','TAPE_LIBRARY','BACKUP_APPLIANCE','JBOD','DISK_SHELF','UPS','RACK_PDU','ATS','STS','RECTIFIER','INVERTER','KVM_CONSOLE','RACK_CONSOLE','CABLE_MANAGER','PBX','SESSION_BORDER_CONTROLLER','VOIP_GATEWAY','OTHER_EQUIPMENT') OR (rack_units BETWEEN 1 AND 100 AND width_mm BETWEEN 1 AND 5000 AND depth_mm BETWEEN 1 AND 5000 AND weight_kg > 0));

ALTER TABLE infranexum_dcim.cable_connection
  ADD COLUMN IF NOT EXISTS cable_type VARCHAR(40) NOT NULL DEFAULT 'OTHER',
  ADD COLUMN IF NOT EXISTS length_meters NUMERIC(12,3) NOT NULL DEFAULT 1,
  ADD COLUMN IF NOT EXISTS manufacturer_partner_id UUID,
  ADD COLUMN IF NOT EXISTS manufacturer_reference VARCHAR(160);

ALTER TABLE infranexum_dcim.cable_connection DROP CONSTRAINT IF EXISTS ck_inx_dcim_cable_length;
ALTER TABLE infranexum_dcim.cable_connection DROP CONSTRAINT IF EXISTS ck_inx_dcim_cable_vendor_ref;
ALTER TABLE infranexum_dcim.cable_connection DROP CONSTRAINT IF EXISTS ck_inx_dcim_cable_type;
ALTER TABLE infranexum_dcim.cable_connection
  ADD CONSTRAINT ck_inx_dcim_cable_length CHECK (length_meters > 0 AND length_meters <= 100000),
  ADD CONSTRAINT ck_inx_dcim_cable_vendor_ref CHECK (manufacturer_reference IS NULL OR manufacturer_partner_id IS NOT NULL),
  ADD CONSTRAINT ck_inx_dcim_cable_type CHECK (cable_type IN ('COPPER_ETHERNET','FIBER_SINGLE_MODE','FIBER_MULTI_MODE','DAC','AOC','COAXIAL','POWER_AC','POWER_DC','SERIAL','USB','HDMI','DISPLAYPORT','TELEPHONE','OTHER'));
